export const CORPUS = Object.freeze(Object.entries(documents).flatMap(([split, categories]) => {
  let index = 0;
  return Object.entries(categories).flatMap(([topic, tuples]) => tuples.map(([language, caseType, text]) => {
    const id = `h2_${split}_${String(++index).padStart(3, '0')}`;
    return Object.freeze({ id, groupId: id, split, language, text,
      expectedTopicId: topic === 'outside' ? null : topic, caseType, provenance: 'synthetic-authored' });
  }));
}));
export const corpus = CORPUS;
export default CORPUS;
